import React, { useState, useEffect } from "react";
import axios from "../../utils/axiosConfig";
import {
  FaUser,
  FaPhone,
  FaEnvelope,
  FaIdCard,
  FaMotorcycle,
  FaMapMarkerAlt,
  FaStar,
  FaEdit,
  FaSave,
  FaTimes,
} from "react-icons/fa";
import "../../assets/css/shipper.css";

const ShipperProfileContent = () => {
  const [profile, setProfile] = useState({});
  const [loading, setLoading] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    fullName: "",
    phoneNumber: "",
    vehicleType: "",
    licensePlate: "",
  });

  const fetchProfileData = async () => {
    setLoading(true);
    try {
      const response = await axios.get("/shipper/info");
      const { user, shipperDetails } = response.data;

      setProfile({ user, shipperDetails });

      setFormData({
        fullName: user.fullName || "",
        phoneNumber: shipperDetails?.phoneNumber || "",
        vehicleType: shipperDetails?.vehicleType || "Motorbike",
        licensePlate: shipperDetails?.licensePlate || "",
      });
    } catch (err) {
      console.error("Lỗi tải hồ sơ:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProfileData();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await axios.put("/shipper/info", {
        fullName: formData.fullName,
        phone: formData.phoneNumber,
        vehicleType: formData.vehicleType,
        licensePlate: formData.licensePlate,
      });
      setIsEditing(false);
      fetchProfileData();
      alert("Cập nhật hồ sơ thành công!");
    } catch (err) {
      alert("Có lỗi xảy ra khi cập nhật.");
    } finally {
      setLoading(false);
    }
  };

  if (loading && !isEditing)
    return <div className="shipper-content">Đang tải dữ liệu...</div>;

  const user = profile.user || {};
  const details = profile.shipperDetails || {};

  return (
    <div className="shipper-profile-container">
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "25px",
        }}
      >
        <h2 style={{ margin: 0 }}>Hồ Sơ Cá Nhân</h2>
        {!isEditing && (
          <button
            className="btn-ship btn-ship-primary"
            onClick={() => setIsEditing(true)}
          >
            <FaEdit /> Chỉnh sửa hồ sơ
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit}>
        <div className="stats-grid">
          {" "}
          {/* Tái sử dụng grid 2 cột từ Dashboard */}
          {/* CỘT 1: THÔNG TIN ĐỊNH DANH */}
          <div
            className="stat-card"
            style={{
              flexDirection: "column",
              alignItems: "flex-start",
              display: "block",
            }}
          >
            <h4 className="profile-card-header">
              <FaUser /> Thông tin định danh
            </h4>

            <div className="profile-input-group">
              <label className="profile-input-label">
                <FaIdCard /> Họ và Tên
              </label>
              <input
                className="ship-input"
                value={formData.fullName}
                onChange={(e) =>
                  setFormData({ ...formData, fullName: e.target.value })
                }
                disabled={!isEditing}
                placeholder="Nhập họ tên..."
              />
            </div>

            <div className="profile-input-group">
              <label className="profile-input-label">
                <FaEnvelope /> Email hệ thống
              </label>
              <input className="ship-input" value={user.email || ""} disabled />
            </div>

            <div className="profile-input-group">
              <label className="profile-input-label">
                <FaPhone /> Số điện thoại (Shipper)
              </label>
              <input
                className="ship-input"
                value={formData.phoneNumber}
                onChange={(e) =>
                  setFormData({ ...formData, phoneNumber: e.target.value })
                }
                disabled={!isEditing}
                placeholder="Nhập số điện thoại liên lạc..."
              />
            </div>
          </div>
          {/* CỘT 2: THÔNG TIN VẬN CHUYỂN */}
          <div
            className="stat-card"
            style={{
              flexDirection: "column",
              alignItems: "flex-start",
              display: "block",
            }}
          >
            <h4 className="profile-card-header">
              <FaMotorcycle /> Thông tin vận chuyển
            </h4>

            <div className="profile-input-group">
              <label className="profile-input-label">Loại phương tiện</label>
              <select
                className="ship-input"
                value={formData.vehicleType}
                onChange={(e) =>
                  setFormData({ ...formData, vehicleType: e.target.value })
                }
                disabled={!isEditing}
              >
                <option value="Motorbike">Xe máy</option>
                <option value="Car">Ô tô</option>
                <option value="Truck">Xe tải</option>
              </select>
            </div>

            <div className="profile-input-group">
              <label className="profile-input-label">Biển số xe</label>
              <input
                className="ship-input"
                value={formData.licensePlate}
                onChange={(e) =>
                  setFormData({ ...formData, licensePlate: e.target.value })
                }
                disabled={!isEditing}
                placeholder="Ví dụ: 29A-123.45"
              />
            </div>

            <div className="profile-input-group">
              <label className="profile-input-label">
                <FaMapMarkerAlt /> Khu vực hoạt động
              </label>
              <div
                className="ship-input"
                style={{ backgroundColor: "#f8f9fa", minHeight: "40px" }}
              >
                {details.workingArea?.length > 0
                  ? details.workingArea.join(", ")
                  : "Toàn quốc"}
              </div>
            </div>
          </div>
        </div>

        {/* PHẦN DƯỚI: TRẠNG THÁI & ĐÁNH GIÁ (Chế độ xem) */}
        {!isEditing && (
          <div
            className="stat-card"
            style={{ marginTop: "20px", justifyContent: "space-around" }}
          >
            <div style={{ textAlign: "center" }}>
              <div style={{ color: "#666", fontSize: "0.9em" }}>
                Trạng thái tài khoản
              </div>
              <div
                className={`badge ${
                  details.status === "ACTIVE"
                    ? "badge-success"
                    : "badge-pending"
                }`}
                style={{ marginTop: "5px" }}
              >
                {details.status === "ACTIVE"
                  ? "Sẵn sàng làm việc"
                  : details.status}
              </div>
            </div>
            <div
              style={{
                textAlign: "center",
                borderLeft: "1px solid #eee",
                paddingLeft: "40px",
              }}
            >
              <div style={{ color: "#666", fontSize: "0.9em" }}>
                Điểm uy tín
              </div>
              <div
                style={{
                  fontSize: "1.2em",
                  fontWeight: "bold",
                  color: "#f39c12",
                }}
              >
                {details.rating || 5} <FaStar />
              </div>
            </div>
          </div>
        )}

        {/* NÚT ĐIỀU KHIỂN KHI EDIT */}
        {isEditing && (
          <div
            style={{
              display: "flex",
              gap: "15px",
              justifyContent: "flex-end",
              marginTop: "30px",
            }}
          >
            <button
              type="button"
              className="btn-ship btn-ship-outline"
              onClick={() => setIsEditing(false)}
            >
              <FaTimes /> Hủy bỏ
            </button>
            <button
              type="submit"
              className="btn-ship btn-ship-success"
              disabled={loading}
            >
              <FaSave /> {loading ? "Đang lưu..." : "Lưu thay đổi"}
            </button>
          </div>
        )}
      </form>
    </div>
  );
};

export default ShipperProfileContent;
